-- Ascend Now — baseline full schema
--
-- This is a single, consolidated migration that reproduces the live Ascend
-- Now database (project ref uqyuczvckqxgtilpzarh) exactly as of 2026-07-01,
-- generated by direct introspection of the live database rather than by
-- replaying history. It replaces two previous, mutually-inconsistent change
-- logs (db/schema/*.sql — 28 numbered files, and the prior contents of
-- supabase/migrations/ — 35 timestamped files) whose own migration-tracking
-- table was empty, meaning they could no longer be trusted as an accurate
-- record of what was actually live. See db/docs/VERIFIED_DATABASE_STATE.md
-- for full narrative context and the exact live data this was derived from.
--
-- This migration is schema-only — it does not restore data (subjects,
-- teachers, students, seed rows for program_types/course_types/curricula,
-- etc.). Run db/scripts/ as needed after applying this to seed lookup data
-- and create your first admin.
--
-- This migration reproduces one known issue that was present in the live
-- database at the time of this snapshot: `zoom_invoices` had no
-- SELECT/INSERT/UPDATE/DELETE grants for `authenticated`, despite RLS
-- policies assuming teachers could insert/read their own rows (see section
-- 13). That gap was confirmed and fixed live immediately after this file
-- was written — see 20260701000001_fix_zoom_invoices_authenticated_grant.sql.
-- Left as-is here (rather than rewritten) since this file is a point-in-time
-- snapshot; anyone applying this baseline from scratch should also apply
-- the follow-up migration.

-- =========================================================================
-- 1. Enum types
-- =========================================================================

CREATE TYPE public.user_role AS ENUM ('teacher', 'student', 'parent', 'performance_coach', 'admin');
CREATE TYPE public.engagement_rating AS ENUM ('low', 'medium', 'high');

-- =========================================================================
-- 2. Sequences (only the two columns that are not IDENTITY columns)
-- =========================================================================

CREATE SEQUENCE public.students_num_seq;
CREATE SEQUENCE public.zoom_invoices_id_seq;

-- =========================================================================
-- 3. Tables (foreign keys added separately in section 5, to avoid ordering
--    problems — every table below only has PRIMARY KEY / UNIQUE / CHECK /
--    DEFAULT constraints inline)
-- =========================================================================

CREATE TABLE public.users (
  id uuid PRIMARY KEY,
  username text NOT NULL UNIQUE,
  email text NOT NULL,
  full_name text,
  role public.user_role NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  avatar_url text
);

CREATE TABLE public.teachers (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  first_name text NOT NULL,
  last_name text,
  country text,
  email text UNIQUE,
  phone_number text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  user_id uuid,
  is_performance_coach boolean NOT NULL DEFAULT false,
  is_active boolean NOT NULL DEFAULT true
);

CREATE TABLE public.teacher_subjects (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  teacher_id bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  subject_id smallint NOT NULL,
  curriculum_id smallint
);

CREATE TABLE public.admins (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  user_id uuid NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.students (
  id text PRIMARY KEY DEFAULT ('S' || (nextval('public.students_num_seq'))::text),
  first_name text NOT NULL,
  last_name text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  parent_full_name text,
  phone_number text,
  email text,
  address text,
  country text
);

CREATE TABLE public.pc_student_assignments (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_id text NOT NULL,
  pc_teacher_id bigint NOT NULL,
  assigned_at timestamptz NOT NULL DEFAULT now(),
  unassigned_at timestamptz
);

CREATE TABLE public.program_types (
  id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL UNIQUE,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  parent_id smallint,
  type text
);

CREATE TABLE public.course_types (
  id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL UNIQUE,
  color text NOT NULL DEFAULT 'slate',
  sort_order smallint NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.subject_categories (
  id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  type text NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT subject_categories_type_check CHECK (type = ANY (ARRAY['academic'::text, 'beyond_academic'::text]))
);

CREATE TABLE public.curricula (
  id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL UNIQUE,
  sort_order smallint NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  added_by_teacher_id integer,
  acknowledged_by_user_id uuid,
  acknowledged_at timestamptz
);

CREATE TABLE public.curriculum_groups (
  id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  curriculum_id smallint NOT NULL,
  name text NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.subjects (
  id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  name text NOT NULL,
  category text NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  category_id smallint,
  added_by_teacher_id integer,
  acknowledged_by_user_id uuid,
  acknowledged_at timestamptz,
  curriculum_group_id smallint,
  board text,
  subject_code text,
  level text
);

CREATE TABLE public.session_logs (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_first_name text,
  student_last_name text,
  session_date date NOT NULL,
  session_duration_hrs numeric,
  program_type_id smallint,
  topic text,
  video_link text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  coordinator_teacher_id bigint,
  teacher_id bigint,
  subject_id smallint,
  curriculum_id smallint,
  student_id text,
  no_show_type text,
  fathom_summary text,
  fathom_summary_doc_url text,
  independent_work text[] DEFAULT '{}'::text[],
  engagement_rating public.engagement_rating,
  performance_feedback text,
  flag_for_coach boolean NOT NULL DEFAULT false,
  flag_category text,
  flag_comments text,
  course_type_id smallint,
  invoice_file_url text,
  CONSTRAINT session_logs_session_duration_hrs_check CHECK (session_duration_hrs >= 0::numeric AND (session_duration_hrs * 4::numeric) = round(session_duration_hrs * 4::numeric)),
  CONSTRAINT session_logs_no_show_type_check CHECK (no_show_type = ANY (ARRAY['no_show_1'::text, 'no_show_2'::text, 'no_show_plus'::text]))
);

CREATE TABLE public.student_packages (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_id text NOT NULL,
  program_type_id smallint,
  total_hours_purchased numeric NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  course_type_id smallint,
  status text NOT NULL DEFAULT 'active',
  closed_at timestamptz,
  CONSTRAINT student_packages_total_hours_purchased_check CHECK (total_hours_purchased >= 0::numeric),
  CONSTRAINT student_packages_status_check CHECK (status = ANY (ARRAY['active'::text, 'closed'::text])),
  CONSTRAINT student_packages_student_id_course_type_id_key UNIQUE (student_id, course_type_id)
);

CREATE TABLE public.package_topups (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_package_id bigint NOT NULL,
  hours_added numeric NOT NULL,
  package_size_label text NOT NULL,
  note text,
  added_by_user_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT package_topups_hours_added_check CHECK (hours_added > 0::numeric)
);

CREATE TABLE public.invoices (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  student_id text NOT NULL,
  period_start date NOT NULL,
  period_end date NOT NULL,
  generated_at timestamptz NOT NULL DEFAULT now(),
  generated_by_user_id uuid NOT NULL,
  total_hours numeric NOT NULL DEFAULT 0,
  doc_url text,
  status text NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  locked_at timestamptz,
  locked_by_user_id uuid,
  CONSTRAINT invoices_status_check CHECK (status = ANY (ARRAY['draft'::text, 'sent'::text, 'locked'::text]))
);

CREATE TABLE public.invoice_line_items (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  invoice_id bigint NOT NULL,
  teacher_id bigint,
  subject_id smallint,
  curriculum_id smallint,
  hours numeric NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  session_count integer NOT NULL DEFAULT 0
);

CREATE TABLE public.invoice_packages (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  invoice_id bigint NOT NULL,
  student_package_id bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT invoice_packages_invoice_id_student_package_id_key UNIQUE (invoice_id, student_package_id)
);

CREATE TABLE public.monthly_reports (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  year smallint NOT NULL,
  month smallint NOT NULL,
  status text NOT NULL DEFAULT 'draft',
  locked_at timestamptz,
  locked_by_user_id uuid,
  period_start date NOT NULL,
  period_end date NOT NULL,
  total_hours numeric NOT NULL DEFAULT 0,
  total_sessions integer NOT NULL DEFAULT 0,
  unique_students integer NOT NULL DEFAULT 0,
  no_show_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  generated_at timestamptz NOT NULL DEFAULT now(),
  generated_by_user_id uuid,
  CONSTRAINT monthly_reports_month_check CHECK (month >= 1 AND month <= 12),
  CONSTRAINT monthly_reports_status_check CHECK (status = ANY (ARRAY['draft'::text, 'locked'::text])),
  CONSTRAINT monthly_reports_year_month_key UNIQUE (year, month)
);

CREATE TABLE public.monthly_report_teacher_stats (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  report_id bigint NOT NULL,
  teacher_id bigint,
  teacher_name text,
  sessions integer NOT NULL DEFAULT 0,
  hours numeric NOT NULL DEFAULT 0
);

CREATE TABLE public.monthly_report_student_stats (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  report_id bigint NOT NULL,
  student_id text,
  student_name text,
  sessions integer NOT NULL DEFAULT 0,
  hours numeric NOT NULL DEFAULT 0
);

CREATE TABLE public.monthly_report_teacher_subject_stats (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  report_id bigint NOT NULL,
  teacher_id bigint,
  teacher_name text,
  subject_id smallint,
  subject_name text,
  subject_level text,
  curriculum_id smallint,
  curriculum_name text,
  program_type_name text,
  sessions integer NOT NULL DEFAULT 0,
  hours numeric NOT NULL DEFAULT 0
);

CREATE TABLE public.monthly_report_student_subject_stats (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  report_id bigint NOT NULL,
  student_id text,
  student_name text,
  subject_id smallint,
  subject_name text,
  subject_level text,
  curriculum_id smallint,
  curriculum_name text,
  sessions integer NOT NULL DEFAULT 0,
  hours numeric NOT NULL DEFAULT 0
);

CREATE TABLE public.monthly_report_subject_stats (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  report_id bigint NOT NULL,
  subject_id smallint,
  subject_name text,
  subject_level text,
  curriculum_id smallint,
  curriculum_name text,
  sessions integer NOT NULL DEFAULT 0,
  hours numeric NOT NULL DEFAULT 0
);

CREATE TABLE public.zoom_invoices (
  id bigint PRIMARY KEY DEFAULT nextval('public.zoom_invoices_id_seq'),
  teacher_id bigint NOT NULL,
  period_month date NOT NULL,
  file_url text NOT NULL,
  uploaded_at timestamptz NOT NULL DEFAULT now(),
  uploaded_by_user_id uuid,
  status text NOT NULL DEFAULT 'pending',
  acknowledged_at timestamptz,
  acknowledged_by_user_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT zoom_invoices_status_check CHECK (status = ANY (ARRAY['pending'::text, 'acknowledged'::text])),
  CONSTRAINT zoom_invoices_teacher_id_period_month_key UNIQUE (teacher_id, period_month)
);

ALTER SEQUENCE public.zoom_invoices_id_seq OWNED BY public.zoom_invoices.id;

-- =========================================================================
-- 4. auth.users FK note
--    `public.users.id` references `auth.users.id` (Supabase-managed schema).
-- =========================================================================

