-- =========================================================================
-- 6. Additional indexes (beyond the PK/UNIQUE indexes created inline above)
-- =========================================================================

CREATE INDEX idx_admins_user_id ON public.admins USING btree (user_id);

CREATE INDEX idx_teachers_user_id ON public.teachers USING btree (user_id);
CREATE INDEX idx_teachers_name ON public.teachers USING btree (first_name, last_name);
CREATE INDEX idx_teachers_is_performance_coach ON public.teachers USING btree (is_performance_coach);

CREATE INDEX idx_teacher_subjects_teacher ON public.teacher_subjects USING btree (teacher_id);
CREATE INDEX idx_teacher_subjects_subject_id ON public.teacher_subjects USING btree (subject_id);
CREATE UNIQUE INDEX teacher_subjects_academic_uq ON public.teacher_subjects USING btree (teacher_id, subject_id, curriculum_id) WHERE (curriculum_id IS NOT NULL);
CREATE UNIQUE INDEX teacher_subjects_non_academic_uq ON public.teacher_subjects USING btree (teacher_id, subject_id) WHERE (curriculum_id IS NULL);

CREATE INDEX idx_pc_assignments_teacher ON public.pc_student_assignments USING btree (pc_teacher_id);
CREATE UNIQUE INDEX uq_active_pc_per_student ON public.pc_student_assignments USING btree (student_id) WHERE (unassigned_at IS NULL);

CREATE UNIQUE INDEX subjects_name_cat_no_group_idx ON public.subjects USING btree (name, category_id) WHERE (curriculum_group_id IS NULL);

CREATE INDEX idx_session_logs_date ON public.session_logs USING btree (session_date);
CREATE INDEX idx_session_logs_teacher_id ON public.session_logs USING btree (teacher_id);
CREATE INDEX idx_session_logs_coordinator_teacher_id ON public.session_logs USING btree (coordinator_teacher_id);
CREATE INDEX idx_session_logs_program ON public.session_logs USING btree (program_type_id);
CREATE INDEX idx_session_logs_course_type ON public.session_logs USING btree (course_type_id);
CREATE INDEX idx_session_logs_curriculum_id ON public.session_logs USING btree (curriculum_id);
CREATE INDEX idx_session_logs_subject_id ON public.session_logs USING btree (subject_id);
CREATE INDEX idx_session_logs_student ON public.session_logs USING btree (student_first_name, student_last_name);

CREATE INDEX idx_invoices_student_id ON public.invoices USING btree (student_id);
CREATE INDEX idx_invoice_line_items_invoice_id ON public.invoice_line_items USING btree (invoice_id);
CREATE INDEX idx_invoice_packages_invoice_id ON public.invoice_packages USING btree (invoice_id);
CREATE INDEX idx_invoice_packages_student_package_id ON public.invoice_packages USING btree (student_package_id);

CREATE INDEX idx_topups_package_id ON public.package_topups USING btree (student_package_id);

CREATE INDEX idx_monthly_reports_year_month ON public.monthly_reports USING btree (year, month);
