CREATE INDEX idx_monthly_report_student_stats_report_id ON public.monthly_report_student_stats USING btree (report_id);
CREATE INDEX idx_monthly_report_teacher_subject_stats_report_id ON public.monthly_report_teacher_subject_stats USING btree (report_id);
