-- =========================================================================
-- 7. Table & column comments
-- =========================================================================

COMMENT ON TABLE public.users IS 'Central identity table, 1-to-1 with auth.users. PASSWORDS ARE NOT STORED HERE — Supabase Auth (auth.users) handles password hashing and verification. Role-specific fields live in teachers / students / etc., linked via user_id.';
COMMENT ON TABLE public.admins IS 'Minimal admin profile, linked to public.users. Admins manage all data; access control comes from users.role = ''admin'', not from anything stored here.';

COMMENT ON COLUMN public.teachers.user_id IS 'Links this teacher profile to their login identity in public.users.';
COMMENT ON COLUMN public.teachers.last_name IS 'Nullable — most rows in source sheet had no surname recorded.';
COMMENT ON COLUMN public.teachers.is_performance_coach IS 'True if this teacher also coordinates sessions (acts as a performance coach). Not a separate role/table — a teacher with extra responsibility.';
COMMENT ON COLUMN public.session_logs.teacher_id IS 'The teacher who taught this session. Auto-filled by the frontend from the logged-in teacher''s profile — never typed manually.';
COMMENT ON COLUMN public.session_logs.coordinator_teacher_id IS 'The performance coach who coordinated this session — actually a teacher row (one with is_performance_coach = true, though this is not DB-enforced). Replaces the old free-text coordinator column.';

-- =========================================================================
-- 8. Functions
-- =========================================================================

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select exists (
    select 1 from public.users
    where id = auth.uid() and role = 'admin'
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_performance_coach()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select exists (
    select 1 from public.users
    where id = auth.uid() and role = 'performance_coach'
  )
$function$;

CREATE OR REPLACE FUNCTION public.my_teacher_id()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select id from public.teachers
  where user_id = auth.uid()
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.get_email_for_username(p_username text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  select email from public.users where username = p_username limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.create_user_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    insert into public.users (id, username, email, full_name, role)
    values (
        new.id,
        coalesce(new.raw_user_meta_data ->> 'username', new.email),
        new.email,
        new.raw_user_meta_data ->> 'full_name',
        coalesce((new.raw_user_meta_data ->> 'role')::public.user_role, 'student'::public.user_role)
    );
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_teacher_profile(p_user_id uuid, p_country text, p_subjects text[])
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_teacher_id bigint;
    v_subject text;
begin
    insert into teachers (user_id, first_name, last_name, country, email, phone_number)
    select
        p_user_id,
        u.full_name,   -- simplest for now; split into first/last later if needed
        null,
        p_country,
        u.email,
        null
    from public.users u
    where u.id = p_user_id
    returning id into v_teacher_id;

    foreach v_subject in array p_subjects
    loop
        insert into teacher_subjects (teacher_id, subject_name)
        values (v_teacher_id, v_subject)
        on conflict (teacher_id, subject_name) do nothing;
    end loop;

    return v_teacher_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_admin_profile(p_user_id uuid)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
    v_admin_id bigint;
begin
    insert into admins (user_id)
    values (p_user_id)
    returning id into v_admin_id;

    return v_admin_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_teacher_pc_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.user_id is not null then
    update public.users
    set role = case
      when NEW.is_performance_coach then 'performance_coach'::public.user_role
      else 'teacher'::public.user_role
    end
    where id = NEW.user_id;
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_self_privilege_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  if exists (
    select 1 from public.users
    where id = auth.uid() and role = 'admin'
  ) then
    return new;
  end if;
  if new.role is distinct from old.role then
    raise exception 'Changing role is not allowed';
  end if;
  if new.is_active is distinct from old.is_active then
    raise exception 'Changing active status is not allowed';
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_session_log_change_in_locked_month()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  old_locked boolean := false;
  new_locked boolean := false;
BEGIN
  -- Editing or deleting a row that already belongs to a locked month is
  -- blocked regardless of what's changing (checked against OLD).
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.monthly_reports mr
      WHERE mr.status = 'locked'
        AND mr.year  = EXTRACT(YEAR FROM OLD.session_date)::smallint
        AND mr.month = EXTRACT(MONTH FROM OLD.session_date)::smallint
    ) INTO old_locked;
  END IF;

  -- Inserting a new row, or moving an existing one, into a locked month is
  -- just as much a change to that month's frozen data (checked against NEW).
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    SELECT EXISTS (
      SELECT 1 FROM public.monthly_reports mr
      WHERE mr.status = 'locked'
        AND mr.year  = EXTRACT(YEAR FROM NEW.session_date)::smallint
        AND mr.month = EXTRACT(MONTH FROM NEW.session_date)::smallint
    ) INTO new_locked;
  END IF;

  IF old_locked THEN
    RAISE EXCEPTION 'Cannot % this session log — % is a locked report month.',
      lower(TG_OP), to_char(OLD.session_date, 'Mon YYYY');
  END IF;

  IF new_locked THEN
    RAISE EXCEPTION 'Cannot % this session log into % — that report month is locked.',
      lower(TG_OP), to_char(NEW.session_date, 'Mon YYYY');
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_locked_monthly_report_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'locked' THEN
    RAISE EXCEPTION 'Cannot modify a locked monthly report.';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_locked_monthly_report_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'locked' THEN
    RAISE EXCEPTION 'Cannot delete a locked monthly report — it also protects that month''s session logs from editing.';
  END IF;
  RETURN OLD;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_locked_report_stat_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  parent_status text;
BEGIN
  SELECT status INTO parent_status FROM public.monthly_reports WHERE id = OLD.report_id;
  IF parent_status = 'locked' THEN
    RAISE EXCEPTION 'Cannot modify stats for a locked monthly report.';
  END IF;
  RETURN OLD;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_locked_invoice_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status = 'locked' THEN
    RAISE EXCEPTION 'Cannot delete a locked invoice';
  END IF;
  RETURN OLD;
END;
$function$;

CREATE OR REPLACE FUNCTION public.on_package_topup_inserted()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE public.student_packages
  SET
    total_hours_purchased = total_hours_purchased + NEW.hours_added,
    updated_at            = now()
  WHERE id = NEW.student_package_id;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.updated_at = now();
    return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.touch_invoices_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.touch_student_packages_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.touch_package_allocations_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

