CREATE TRIGGER trg_create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();

CREATE TRIGGER trg_prevent_privilege_escalation BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION public.prevent_self_privilege_escalation();
CREATE TRIGGER trg_touch_users BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

CREATE TRIGGER trg_sync_teacher_pc_role AFTER INSERT OR UPDATE OF is_performance_coach ON public.teachers FOR EACH ROW EXECUTE FUNCTION public.sync_teacher_pc_role();
CREATE TRIGGER trg_touch_teachers BEFORE UPDATE ON public.teachers FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

CREATE TRIGGER trg_touch_admins BEFORE UPDATE ON public.admins FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

CREATE TRIGGER trg_prevent_session_log_change_in_locked_month BEFORE INSERT OR DELETE OR UPDATE ON public.session_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_session_log_change_in_locked_month();
CREATE TRIGGER trg_touch_session_logs BEFORE UPDATE ON public.session_logs FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

CREATE TRIGGER trg_touch_student_packages_updated_at BEFORE UPDATE ON public.student_packages FOR EACH ROW EXECUTE FUNCTION public.touch_student_packages_updated_at();

CREATE TRIGGER trg_package_topup_update_hours AFTER INSERT ON public.package_topups FOR EACH ROW EXECUTE FUNCTION public.on_package_topup_inserted();

CREATE TRIGGER trg_touch_invoices_updated_at BEFORE UPDATE ON public.invoices FOR EACH ROW EXECUTE FUNCTION public.touch_invoices_updated_at();
CREATE TRIGGER trg_prevent_locked_invoice_delete BEFORE DELETE ON public.invoices FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_invoice_delete();

CREATE TRIGGER trg_prevent_locked_monthly_report_update BEFORE UPDATE ON public.monthly_reports FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_monthly_report_update();
CREATE TRIGGER trg_prevent_locked_monthly_report_delete BEFORE DELETE ON public.monthly_reports FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_monthly_report_delete();

CREATE TRIGGER trg_prevent_locked_teacher_stat_change BEFORE DELETE OR UPDATE ON public.monthly_report_teacher_stats FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_report_stat_change();
CREATE TRIGGER trg_prevent_locked_student_stat_change BEFORE DELETE OR UPDATE ON public.monthly_report_student_stats FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_report_stat_change();
CREATE TRIGGER trg_prevent_locked_teacher_subject_stat_change BEFORE DELETE OR UPDATE ON public.monthly_report_teacher_subject_stats FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_report_stat_change();
CREATE TRIGGER trg_prevent_locked_student_subject_stat_change BEFORE DELETE OR UPDATE ON public.monthly_report_student_subject_stats FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_report_stat_change();
CREATE TRIGGER trg_prevent_locked_subject_stat_change BEFORE DELETE OR UPDATE ON public.monthly_report_subject_stats FOR EACH ROW EXECUTE FUNCTION public.prevent_locked_report_stat_change();

-- Event trigger: automatically enables RLS on any new table created in
-- `public` from now on (fail-closed default — a new table is fully locked,
-- including to admins, until policies are added). Not something anyone
-- deliberately designed — appears to be a Supabase project default — but
-- reproduced here since it is genuinely active on the live project.
CREATE EVENT TRIGGER ensure_rls ON ddl_command_end
  WHEN TAG IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
  EXECUTE FUNCTION public.rls_auto_enable();

