-- =========================================================================
-- 11. Row Level Security — policies
--
-- Reproduced exactly as found live, INCLUDING duplicate/overlapping
-- policies that are functionally redundant (e.g. two INSERT policies on
-- session_logs implementing the same check two different ways). These are
-- leftovers from iterative migrations, not something introduced here — see
-- db/docs/VERIFIED_DATABASE_STATE.md for the full list and a note that
-- consolidating them is a worthwhile follow-up, done deliberately rather
-- than silently in this baseline.
-- =========================================================================

-- users
CREATE POLICY "Admins can do everything on users" ON public.users FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Performance coaches can read users" ON public.users FOR SELECT USING (public.is_performance_coach());
CREATE POLICY "Users can read their own row" ON public.users FOR SELECT USING (id = auth.uid());
CREATE POLICY "Users can update their own row" ON public.users FOR UPDATE USING (auth.uid() = id) WITH CHECK (auth.uid() = id);

-- teachers
CREATE POLICY "Admins can do everything on teachers" ON public.teachers FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Any authenticated user can read teacher names" ON public.teachers FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Any logged-in user can read performance coaches" ON public.teachers FOR SELECT USING (is_performance_coach = true AND auth.uid() IS NOT NULL);
CREATE POLICY "Teachers can read their own row" ON public.teachers FOR SELECT USING (user_id = auth.uid());
CREATE POLICY "Teachers can update their own teacher profile" ON public.teachers FOR UPDATE USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- teacher_subjects
CREATE POLICY "Admins can do everything on teacher_subjects" ON public.teacher_subjects FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Admins can manage all teacher_subjects" ON public.teacher_subjects FOR ALL
  USING (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role))
  WITH CHECK (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role));
CREATE POLICY "Teachers can delete their own subjects" ON public.teacher_subjects FOR DELETE
  USING (EXISTS (SELECT 1 FROM public.teachers WHERE teachers.id = teacher_subjects.teacher_id AND teachers.user_id = auth.uid()));
CREATE POLICY "Teachers can insert their own subjects" ON public.teacher_subjects FOR INSERT
  WITH CHECK (EXISTS (SELECT 1 FROM public.teachers WHERE teachers.id = teacher_subjects.teacher_id AND teachers.user_id = auth.uid()));
CREATE POLICY "Teachers can read their own subjects" ON public.teacher_subjects FOR SELECT
  USING (EXISTS (SELECT 1 FROM public.teachers WHERE teachers.id = teacher_subjects.teacher_id AND teachers.user_id = auth.uid()));

-- admins
CREATE POLICY "Admins can do everything on admins" ON public.admins FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- students
CREATE POLICY "Authenticated users can insert students" ON public.students FOR INSERT TO authenticated WITH CHECK (true);
CREATE POLICY "Authenticated users can read students" ON public.students FOR SELECT TO authenticated USING (true);
CREATE POLICY "Authenticated users can update students" ON public.students FOR UPDATE TO authenticated USING (true);

-- pc_student_assignments
CREATE POLICY "admin_all_pc_assignments" ON public.pc_student_assignments FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "pc_assign_unassigned_student_to_self" ON public.pc_student_assignments FOR INSERT
  WITH CHECK (public.is_performance_coach() AND pc_teacher_id = public.my_teacher_id()
    AND NOT EXISTS (SELECT 1 FROM public.pc_student_assignments existing WHERE existing.student_id = pc_student_assignments.student_id AND existing.unassigned_at IS NULL));
CREATE POLICY "pc_read_own_assignments" ON public.pc_student_assignments FOR SELECT
  USING (public.is_performance_coach() AND pc_teacher_id = public.my_teacher_id());
CREATE POLICY "pc_unassign_own_students" ON public.pc_student_assignments FOR UPDATE
  USING (public.is_performance_coach() AND pc_teacher_id = public.my_teacher_id())
  WITH CHECK (public.is_performance_coach() AND pc_teacher_id = public.my_teacher_id());

-- program_types
CREATE POLICY "Admins can do everything on program_types" ON public.program_types FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Any logged-in user can read program_types" ON public.program_types FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Authenticated users can read program_types" ON public.program_types FOR SELECT USING (auth.uid() IS NOT NULL);

-- course_types
CREATE POLICY "Admins can manage course_types" ON public.course_types FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Any logged-in user can read course_types" ON public.course_types FOR SELECT USING (auth.uid() IS NOT NULL);

-- subject_categories
CREATE POLICY "Admins can do everything on subject_categories" ON public.subject_categories FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Admins can manage all subject_categories" ON public.subject_categories FOR ALL
  USING (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role))
  WITH CHECK (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role));
CREATE POLICY "Performance coaches can manage subject_categories" ON public.subject_categories FOR ALL USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());
CREATE POLICY "Performance coaches can insert subject_categories" ON public.subject_categories FOR INSERT WITH CHECK (public.is_performance_coach());
CREATE POLICY "Any logged-in user can read subject_categories" ON public.subject_categories FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Authenticated users can read subject_categories" ON public.subject_categories FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Performance coaches can update subject_categories" ON public.subject_categories FOR UPDATE USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());

-- curricula
CREATE POLICY "Admins can do everything on curricula" ON public.curricula FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Admins can manage all curricula" ON public.curricula FOR ALL
  USING (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role))
  WITH CHECK (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role));
CREATE POLICY "Authenticated users can insert curricula" ON public.curricula FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Performance coaches can insert curricula" ON public.curricula FOR INSERT WITH CHECK (public.is_performance_coach());
CREATE POLICY "Any logged-in user can read curricula" ON public.curricula FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Authenticated users can read curricula" ON public.curricula FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Performance coaches can update curricula" ON public.curricula FOR UPDATE USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());

-- curriculum_groups
CREATE POLICY "Admins can do everything on curriculum_groups" ON public.curriculum_groups FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Performance coaches can manage curriculum_groups" ON public.curriculum_groups FOR ALL USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());
CREATE POLICY "Any logged-in user can read curriculum_groups" ON public.curriculum_groups FOR SELECT USING (auth.uid() IS NOT NULL);

-- subjects
CREATE POLICY "Admins can do everything on subjects" ON public.subjects FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Admins can manage all subjects" ON public.subjects FOR ALL
  USING (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role))
  WITH CHECK (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role));
CREATE POLICY "Performance coaches can manage subjects" ON public.subjects FOR ALL USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());
CREATE POLICY "Authenticated users can insert subjects" ON public.subjects FOR INSERT WITH CHECK (auth.uid() IS NOT NULL);
CREATE POLICY "Performance coaches can insert subjects" ON public.subjects FOR INSERT WITH CHECK (public.is_performance_coach());
CREATE POLICY "Any logged-in user can read subjects" ON public.subjects FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Authenticated users can read subjects" ON public.subjects FOR SELECT USING (auth.uid() IS NOT NULL);
CREATE POLICY "Performance coaches can update subjects" ON public.subjects FOR UPDATE USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());

-- session_logs
CREATE POLICY "Admins can do everything on session_logs" ON public.session_logs FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Admins can manage all session_logs" ON public.session_logs FOR ALL
  USING (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role))
  WITH CHECK (EXISTS (SELECT 1 FROM public.users WHERE users.id = auth.uid() AND users.role = 'admin'::public.user_role));
CREATE POLICY "Teachers can insert their own session logs" ON public.session_logs FOR INSERT WITH CHECK (teacher_id = public.my_teacher_id());
CREATE POLICY "Teachers can insert their own session_logs" ON public.session_logs FOR INSERT
  WITH CHECK (EXISTS (SELECT 1 FROM public.teachers WHERE teachers.id = session_logs.teacher_id AND teachers.user_id = auth.uid()));
CREATE POLICY "PCs can read sessions for assigned students" ON public.session_logs FOR SELECT
  USING (public.is_performance_coach() AND student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL));
CREATE POLICY "Performance coaches can read all session_logs" ON public.session_logs FOR SELECT USING (public.is_performance_coach());
CREATE POLICY "Teachers can read their own session logs" ON public.session_logs FOR SELECT USING (teacher_id = public.my_teacher_id());
CREATE POLICY "Teachers can read their own session_logs" ON public.session_logs FOR SELECT
  USING (EXISTS (SELECT 1 FROM public.teachers WHERE teachers.id = session_logs.teacher_id AND teachers.user_id = auth.uid()));
CREATE POLICY "Performance coaches can update session_logs" ON public.session_logs FOR UPDATE USING (public.is_performance_coach()) WITH CHECK (public.is_performance_coach());

-- student_packages
CREATE POLICY "admin_all_student_packages" ON public.student_packages FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "pc_manage_assigned_packages" ON public.student_packages FOR ALL
  USING (public.is_performance_coach() AND student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL))
  WITH CHECK (public.is_performance_coach() AND student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL));

-- package_topups
CREATE POLICY "admin_all_topups" ON public.package_topups FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "pc_insert_own_topups" ON public.package_topups FOR INSERT
  WITH CHECK (public.is_performance_coach() AND student_package_id IN (
    SELECT sp.id FROM public.student_packages sp WHERE sp.student_id IN (
      SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL)));
CREATE POLICY "pc_select_own_topups" ON public.package_topups FOR SELECT
  USING (public.is_performance_coach() AND student_package_id IN (
    SELECT sp.id FROM public.student_packages sp WHERE sp.student_id IN (
      SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL)));

-- invoices
CREATE POLICY "admin_all_invoices" ON public.invoices FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "pc_manage_assigned_invoices" ON public.invoices FOR ALL
  USING (public.is_performance_coach() AND student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL))
  WITH CHECK (public.is_performance_coach() AND student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL));

-- invoice_line_items
CREATE POLICY "admin_all_line_items" ON public.invoice_line_items FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "pc_manage_line_items" ON public.invoice_line_items FOR ALL
  USING (public.is_performance_coach() AND invoice_id IN (SELECT i.id FROM public.invoices i WHERE i.student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL)))
  WITH CHECK (public.is_performance_coach() AND invoice_id IN (SELECT i.id FROM public.invoices i WHERE i.student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL)));

-- invoice_packages
CREATE POLICY "admin_all_invoice_packages" ON public.invoice_packages FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "pc_manage_invoice_packages" ON public.invoice_packages FOR ALL
  USING (public.is_performance_coach() AND invoice_id IN (SELECT i.id FROM public.invoices i WHERE i.student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL)))
  WITH CHECK (public.is_performance_coach() AND invoice_id IN (SELECT i.id FROM public.invoices i WHERE i.student_id IN (SELECT pc_student_assignments.student_id FROM public.pc_student_assignments WHERE pc_student_assignments.pc_teacher_id = public.my_teacher_id() AND pc_student_assignments.unassigned_at IS NULL)));

-- monthly_reports
CREATE POLICY "admins manage monthly_reports" ON public.monthly_reports FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "teachers read locked monthly_reports" ON public.monthly_reports FOR SELECT USING (status = 'locked'::text);

-- monthly_report_teacher_stats
CREATE POLICY "admins manage monthly_report_teacher_stats" ON public.monthly_report_teacher_stats FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "teachers read own monthly_report_teacher_stats" ON public.monthly_report_teacher_stats FOR SELECT
  USING (teacher_id = public.my_teacher_id() AND EXISTS (SELECT 1 FROM public.monthly_reports mr WHERE mr.id = monthly_report_teacher_stats.report_id AND mr.status = 'locked'::text));

-- monthly_report_student_stats
CREATE POLICY "admins manage monthly_report_student_stats" ON public.monthly_report_student_stats FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- monthly_report_teacher_subject_stats
CREATE POLICY "admins manage monthly_report_teacher_subject_stats" ON public.monthly_report_teacher_subject_stats FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "teachers read own monthly_report_teacher_subject_stats" ON public.monthly_report_teacher_subject_stats FOR SELECT
  USING (teacher_id = public.my_teacher_id() AND EXISTS (SELECT 1 FROM public.monthly_reports mr WHERE mr.id = monthly_report_teacher_subject_stats.report_id AND mr.status = 'locked'::text));

-- monthly_report_student_subject_stats
CREATE POLICY "admins manage monthly_report_student_subject_stats" ON public.monthly_report_student_subject_stats FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());

-- monthly_report_subject_stats
CREATE POLICY "admins manage monthly_report_subject_stats" ON public.monthly_report_subject_stats FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "teachers read locked monthly_report_subject_stats" ON public.monthly_report_subject_stats FOR SELECT
  USING (EXISTS (SELECT 1 FROM public.monthly_reports mr WHERE mr.id = monthly_report_subject_stats.report_id AND mr.status = 'locked'::text));

-- zoom_invoices
CREATE POLICY "Admins can manage zoom invoices" ON public.zoom_invoices FOR ALL USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY "Teachers can upload their own zoom invoices" ON public.zoom_invoices FOR INSERT WITH CHECK (teacher_id = public.my_teacher_id());
CREATE POLICY "Teachers can view their own zoom invoices" ON public.zoom_invoices FOR SELECT USING (teacher_id = public.my_teacher_id() OR public.is_admin());
CREATE POLICY "Teachers can replace their own pending zoom invoices" ON public.zoom_invoices FOR UPDATE
  USING (teacher_id = public.my_teacher_id() AND status = 'pending'::text)
  WITH CHECK (teacher_id = public.my_teacher_id() AND status = 'pending'::text);

-- =========================================================================
-- 12. Grants
--
-- RLS policies only take effect on top of these base grants — a role with
-- no grant is blocked before RLS is ever evaluated. Reproduced exactly as
-- found live, including the zoom_invoices gap flagged at the top of this
-- file (authenticated has no SELECT/INSERT/UPDATE/DELETE grant there at
-- all, despite policies that assume it does).
-- =========================================================================

GRANT SELECT ON TABLE public.users TO anon;

GRANT SELECT, INSERT, UPDATE ON TABLE public.users TO authenticated; -- no DELETE, by design
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.teachers TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.teacher_subjects TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.admins TO authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.students TO authenticated; -- no DELETE, by design
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.pc_student_assignments TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.program_types TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.course_types TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.subject_categories TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.curricula TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.curriculum_groups TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.subjects TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.session_logs TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.student_packages TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.package_topups TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.invoices TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.invoice_line_items TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.invoice_packages TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.monthly_reports TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.monthly_report_teacher_stats TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.monthly_report_student_stats TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.monthly_report_teacher_subject_stats TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.monthly_report_student_subject_stats TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.monthly_report_subject_stats TO authenticated;
-- NOTE: public.zoom_invoices intentionally has NO grant to authenticated
-- here, matching the live database at the time this file was written (see
-- file header) — that gap is fixed by the very next migration,
-- 20260701000001_fix_zoom_invoices_authenticated_grant.sql.

-- The original 6-table design also granted service_role explicit full
-- access (redundant with service_role's RLS-bypass, but reproduced exactly
-- since it's genuinely present live). Later-added tables rely solely on
-- service_role's implicit bypass instead.
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.admins TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.program_types TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.session_logs TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.teacher_subjects TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.teachers TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.users TO service_role;

-- =========================================================================
-- 13. Storage buckets & policies
-- =========================================================================

INSERT INTO storage.buckets (id, name, public) VALUES
  ('avatars', 'avatars', true),
  ('session-summaries', 'session-summaries', true),
  ('session-invoices', 'session-invoices', true)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "Avatars are publicly readable" ON storage.objects FOR SELECT USING (bucket_id = 'avatars');
CREATE POLICY "Users can upload their own avatar" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can update their own avatar" ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);

CREATE POLICY "Authenticated users can read summaries" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'session-summaries');
CREATE POLICY "Authenticated users can upload summaries" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'session-summaries');

CREATE POLICY "Authenticated users can read invoices" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'session-invoices');
CREATE POLICY "Authenticated users can upload invoices" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'session-invoices');

-- Note (from the security advisor): all three buckets are public and their
-- SELECT policies allow listing all objects in the bucket, not just fetching
-- by known URL. Low risk for this use case, reproduced as-is; tighten later
-- if file enumeration becomes a concern.

